const R_PLATE = 104, PLATE_H = 5, R_PAD = 52, PAD_H = 2.4, BASE = PLATE_H + PAD_H, CORE = 30;
const ORBITS = [76, 95], COL = 46, COL_H = 16, TOP = 5 * COL_H;
